            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xF95A0CF88136D612ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0x5C113776798266ACULL) ^ aOUSaltA[(((511U - aIndex) + 326U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x80AB2D376218CFC1ULL), 5U);
