            aCross = (RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 7279U)) & S_BLOCK1], 13U) ^ RotL64(aCrystalLaneA[((S_BLOCK1 - aIndex + 3205U)) & S_BLOCK1], 29U));
