            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 43U) ^ RotL64(aIngress, 58U)) ^ (RotL64(aPrevious, 11U) + RotL64(aCarry, 23U));
