            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0x444A36D823D57D1EULL) + aOUSaltB[(((511U - aIndex) + 423U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x933C7DF6388B6CECULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB56E1D655835131DULL), 27U);
