            aOrbiterC = RotL64((aOrbiterC * 0x7ADD8BD1F32F5857ULL), 21U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0xF8D974D5D48C2443ULL) + aOUSaltB[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0xED25CA9F2DA60FA3ULL) ^ aOUSaltE[((aIndex + 500U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xB859C16D28B0CB79ULL), 39U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x65B2C17BB17838A4ULL;
