            aWandererB = aWandererB ^ ((((RotL64(aPrevious, 51U) + RotL64(aOrbiterG, 3U)) + aOrbiterE) + RotL64(aCarry, 11U)) + aWUSaltB[(((511U - aIndex) + 201U)) & S_SALT1]);
