            aWandererF = aWandererF ^ (((RotL64(aPrevious, 5U) + RotL64(aOrbiterK, 56U)) + aOrbiterH) + aWUSaltF[(((511U - aIndex) + 287U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aCross, 21U) + RotL64(aOrbiterF, 3U)) + aOrbiterI) + aWUSaltD[((aIndex + 110U)) & S_SALT1]);
