            aWandererC = aWandererC + (((RotL64(aScatter, 3U) + aOrbiterJ) + RotL64(aOrbiterE, 43U)) + RotL64(aCarry, 27U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 27U) + aOrbiterH) + RotL64(aOrbiterF, 48U));
